var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">'+els+'</svg>';
console.log('Generated SVG ('+DATA.label+'):');
console.log(svg);
console.log('OK - '+DATA.shapes.length+' shapes, '+svg.length+' chars');
